 'Tokyo Trip Expenses':276,
 'Expenditures of Maui trip.':280,
 'Expenses for the trip to Santorini':277
}

# Parse lines
line_re=re.compile(r"^-\s*(?P<payer>.+?)\s+paid\s+\$(?P<amount>[0-9]+(?:\.[0-9]+)?)\s+for\s+\"(?P<desc>.+?)\"\.?\s*Owed equally by\s+(?P<debtors>.+?)\.?\s*$")
parsed=[]
for trip,nid in trip_notes.items():
    note=apis.simple_note.show_note(note_id=nid, access_token=simple_token)
    for line in note['content'].splitlines():
        line=line.strip()
        if not line.startswith('- '):
            continue
        m=line_re.match(line)
        if not m:
            raise ValueError(f'Parse fail: trip={trip} line={line}')
        payer=m.group('payer').strip(); amount=float(m.group('amount')); desc=m.group('desc').strip()
        debtors_raw=m.group('debtors').strip()
        debtors_raw=debtors_raw.replace(' and ', ', ').replace(' & ', ', ')
        debtor_names=[d.strip() for d in debtors_raw.split(',') if d.strip()]
        parsed.append({'trip':trip,'group_id':trip_group_ids[trip],'payer_name':payer,'paid_amount':amount,'description':desc,'debtor_names':debtor_names,'source_line':line})

# Identity resolution first-name -> phone contact email constrained by group membership
# fetch groups members
members_by_group={}
for trip,gid in trip_group_ids.items():
    g=apis.splitwise.show_group(group_id=gid, access_token=split_token)
    members_by_group[gid]=g.get('members',[])

# fetch phone contacts all pages
phone_contacts=[]
page_index=0; page_limit=20
while True:
    page=apis.phone.search_contacts(access_token=phone_token, query='', page_index=page_index, page_limit=page_limit)
    if not page: break
    phone_contacts.extend(page)
    if len(page) < page_limit: break
    page_index += 1

contacts_by_first={}
for c in phone_contacts:
    fn=(c.get('first_name') or '').strip().lower()
    if fn:
        contacts_by_first.setdefault(fn,[]).append(c)

unique_first=set()
appear_groups_by_first={}
for e in parsed:
    payer_fn=e['payer_name'].split()[0].lower(); unique_first.add(payer_fn); appear_groups_by_first.setdefault(payer_fn,set()).add(e['group_id'])
    for dn in e['debtor_names']:
        fn=dn.split()[0].lower(); unique_first.add(fn); appear_groups_by_first.setdefault(fn,set()).add(e['group_id'])

resolution={}
for fn in unique_first:
    candidates=contacts_by_first.get(fn,[])
    if len(candidates)==1:
        resolution[fn]=candidates[0]
    else:
        allowed_emails=set()
        for gid in appear_groups_by_first.get(fn,set()):
            for mem in members_by_group.get(gid,[]):
                allowed_emails.add(mem.get('email'))
        matched=[c for c in candidates if c.get('email') in allowed_emails]
        if len(matched)!=1:
            raise SystemExit(f'Unresolved for {fn}: candidates={len(candidates)} matched={len(matched)}')
        resolution[fn]=matched[0]

# Build expenses payloads (including payer if listed in owed equally)
expenses_to_create=[]
for e in parsed:
    payer_fn=e['payer_name'].split()[0].lower(); payer_email=resolution[payer_fn]['email']
    debtor_emails=[resolution[dn.split()[0].lower()]['email'] for dn in e['debtor_names']]
    expenses_to_create.append({'group_id':e['group_id'],'description':e['description'],'paid_amount':e['paid_amount'],'payer_email':payer_email,'debtor_emails':debtor_emails,'source_line':e['source_line']})

print('About to create', len(expenses_to_create), 'expenses')

# Create expenses
results=[]
for i,ex in enumerate(expenses_to_create, start=1):
    try:
        r=apis.splitwise.record_expense(description=ex['description'], paid_amount=ex['paid_amount'], payer_email=ex['payer_email'], debtor_emails=ex['debtor_emails'], group_id=ex['group_id'], access_token=split_token)
        results.append({'i':i,'ok':True,'expense_id':r.get('expense_id'),'message':r.get('message')})
        print('CREATED', i, 'expense_id', r.get('expense_id'))
    except Exception as e:
        results.append({'i':i,'ok':False,'error':str(e)})
        print('FAILED', i, str(e)[:200])

ok_count=sum(1 for x in results if x['ok'])
fail_count=len(results)-ok_count
print('Create results: ok', ok_count,'fail',fail_count)
print('First failures:', [r for r in results if not r['ok']][:3])

